/**
 * Service worker: app shell caching and an offline fallback.
 *
 * Written by hand rather than generated by `next-pwa`/Serwist. The app has no
 * component library and no build plugins by design, and what it needs here is
 * about forty lines of well-understood cache rules — a generator would add a
 * build step and a dependency to produce something larger and harder to reason
 * about.
 *
 * WHAT THIS DELIBERATELY DOES NOT CACHE: page HTML and RSC payloads.
 *
 * That is a security decision, not an oversight. This dashboard holds customer
 * names, addresses and phone numbers, and the only thing protecting them is the
 * session cookie checked in `proxy.ts`. A cached page is served without ever
 * reaching that check, so caching authenticated HTML would mean anyone holding
 * the unlocked phone could read customer data back out of the cache after a
 * logout, or after the session expired. Static build assets carry no customer
 * data and are safe to keep; pages are not.
 *
 * The practical win is still the one that matters: on launch the JS and CSS
 * come straight from disk instead of the network, so the shell paints
 * immediately rather than showing a blank screen while Vercel wakes up.
 */

const VERSION = 'v1';
const STATIC_CACHE = `nolan-static-${VERSION}`;
const OFFLINE_URL = '/offline';

/**
 * The offline page and the icons around it. Everything else is cached as it is
 * requested — the build assets have hashed filenames that are only knowable at
 * build time, and precaching them would need exactly the build step this avoids.
 */
const PRECACHE_URLS = [OFFLINE_URL, '/icons/icon-192.png', '/manifest.webmanifest'];

self.addEventListener('install', (event) => {
  event.waitUntil(
    (async () => {
      const cache = await caches.open(STATIC_CACHE);
      // Individually, not `addAll`: one 404 would otherwise reject the whole
      // install and leave the app with no service worker at all.
      await Promise.all(
        PRECACHE_URLS.map((url) => cache.add(url).catch(() => undefined)),
      );
      await self.skipWaiting();
    })(),
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      const names = await caches.keys();
      await Promise.all(
        names
          .filter((name) => name.startsWith('nolan-') && name !== STATIC_CACHE)
          .map((name) => caches.delete(name)),
      );
      await self.clients.claim();
    })(),
  );
});

/** Hashed, immutable build output — safe to serve from cache forever. */
function isImmutableAsset(url) {
  return url.pathname.startsWith('/_next/static/');
}

/** Icons and the manifest: stable URLs, no customer data, worth keeping. */
function isPublicAsset(url) {
  return url.pathname.startsWith('/icons/') || url.pathname === '/manifest.webmanifest';
}

self.addEventListener('fetch', (event) => {
  const { request } = event;

  if (request.method !== 'GET') return;

  const url = new URL(request.url);

  // Same-origin only. R2 invoice PDFs and anything else cross-origin go
  // straight to the network.
  if (url.origin !== self.location.origin) return;

  // A page navigation. Always the network first, because the response depends
  // on the session and on data that changes constantly. If the network is gone,
  // show the offline page rather than the browser's error screen.
  if (request.mode === 'navigate') {
    event.respondWith(
      (async () => {
        try {
          return await fetch(request);
        } catch {
          const cache = await caches.open(STATIC_CACHE);
          const offline = await cache.match(OFFLINE_URL);
          return (
            offline ??
            new Response('You are offline.', {
              status: 503,
              headers: { 'Content-Type': 'text/plain' },
            })
          );
        }
      })(),
    );
    return;
  }

  if (!isImmutableAsset(url) && !isPublicAsset(url)) return;

  // Cache-first. This is what removes the blank launch: the shell's JS and CSS
  // come off disk instead of waiting on a round trip.
  event.respondWith(
    (async () => {
      const cache = await caches.open(STATIC_CACHE);
      const hit = await cache.match(request);
      if (hit) return hit;

      const response = await fetch(request);
      // Opaque and error responses are not worth storing, and storing an error
      // would pin it until the next version bump.
      if (response.ok && response.type === 'basic') {
        cache.put(request, response.clone());
      }
      return response;
    })(),
  );
});

/**
 * Lets the app drop everything on logout. Belt and braces — no customer data is
 * cached in the first place — but it keeps the guarantee simple to state: after
 * a logout there is nothing of this session left on the device.
 */
self.addEventListener('message', (event) => {
  if (event.data === 'nolan-clear-caches') {
    event.waitUntil(
      (async () => {
        const names = await caches.keys();
        await Promise.all(
          names.filter((n) => n.startsWith('nolan-')).map((n) => caches.delete(n)),
        );
      })(),
    );
  }
});
